function Header({ cp, nav }: { cp: Page; nav: (p: Page) => void }) {
  const [mo, setMo] = useState(false)
  const [hov, setHov] = useState<string | null>(null)
  const [sc, setSc] = useState(false)
  const dt = useRef<NodeJS.Timeout | null>(null)
  useEffect(() => { const h = () => setSc(window.scrollY > 10); window.addEventListener('scroll', h); return () => window.removeEventListener('scroll', h) }, [])
  const mh = useCallback((l: string) => { if (dt.current) clearTimeout(dt.current); setHov(l) }, [])
  const ml = useCallback(() => { dt.current = setTimeout(() => setHov(null), 150) }, [])
  const go = (p: Page) => { nav(p); setHov(null); setMo(false) }
  return (
    <header className="sticky top-0 z-50 w-full bg-white" style={sc ? { boxShadow: '0 2px 8px rgba(0,0,0,0.15)' } : {}}>
      <div className="bg-[#1c1c1c]"><div className={CNT}><div className="flex items-center justify-between h-[25px]">
        <span className="text-[12px] font-normal text-[#ebedef] tracking-wide cursor-pointer hover:text-white transition-colors">automationtechnology.com.pk</span>
        <div className="hidden md:flex items-center gap-5">{TOP_LINKS.map(l => (
          <button key={l} onClick={() => go(TOP_MAP[l])} className="text-[12px] font-normal text-[#ebedef] hover:text-white transition-colors">{l}</button>
        ))}</div>
      </div></div></div>
      <div className="h-px bg-[#e0e0e0]" />
      <div className="bg-white"><div className={CNT}><div className="flex items-center justify-between h-[75px]">
        <button onClick={() => go('home')} className="flex items-center h-full shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-[#00aa73] rounded flex items-center justify-center"><span className="text-white font-bold text-xl">MS</span></div>
            <div className="hidden sm:block"><div className="text-[15px] font-semibold text-[#1c1c1c] leading-tight">MS Automation</div><div className="text-[12px] text-[#666] leading-tight">Technology</div></div>
          </div>
        </button>
        <div className="hidden lg:flex items-center gap-6 flex-1 ml-8">
          <div className="shrink-0 mr-2"><div className="text-[13px] font-medium text-[#1c1c1c] tracking-[0.05em] uppercase">Authorized Festo Distributor</div><div className="h-px bg-[#00aa73] w-full mt-1" /></div>
          <nav className="flex items-center">{NAV.map(item => (
            <div key={item.p} className="relative" onMouseEnter={() => item.dd && mh(item.l)} onMouseLeave={() => item.dd && ml()}>
              <button onClick={() => !item.dd && go(item.p)} className={`px-3 py-2 text-[13px] font-normal uppercase tracking-[0.08em] transition-colors whitespace-nowrap ${cp === item.p ? 'text-[#00aa73] border-b-2 border-[#00aa73]' : 'text-[#1c1c1c] hover:text-[#00aa73]'}`}>
                {item.l}{item.dd && <svg className="inline-block w-3 h-3 ml-1 opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>}
              </button>
              {item.dd && hov === item.l && (
                <div className="absolute top-full left-0 mt-0 bg-white border border-gray-200 shadow-lg min-w-[220px] py-2" onMouseEnter={() => mh(item.l)} onMouseLeave={() => ml()}>
                  {item.dd.map(sub => (<button key={sub} onClick={() => go(item.p)} className="block w-full text-left px-4 py-2 text-[13px] text-[#1c1c1c] hover:text-[#00aa73] hover:bg-gray-50 transition-colors">{sub}</button>))}
                </div>
              )}
            </div>
          ))}</nav>
        </div>
        <div className="flex items-center gap-3">
          <a href="https://www.festo.com" target="_blank" rel="noopener noreferrer" className="hidden md:inline-flex text-[13px] font-normal uppercase tracking-[0.05em] text-[#00aa73] hover:text-[#008c5e] transition-colors">Festo.com</a>
          <div className="hidden sm:block w-px h-5 bg-gray-300" />
          <button onClick={() => go('contact')} className="hidden sm:inline-flex px-4 py-1.5 text-[12px] font-normal uppercase tracking-[0.05em] text-[#00aa73] border border-[#00aa73] hover:bg-[#00aa73] hover:text-white transition-all">Contact Us</button>
          <button onClick={() => setMo(!mo)} className="lg:hidden p-2 text-[#1c1c1c] hover:text-[#00aa73]" aria-label="Menu">{mo ? <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>}</button>
        </div>
      </div></div></div>
      {mo && (
        <div className="lg:hidden border-t border-gray-200 bg-white">
          <div className={CNT}>
            <div className="py-4 space-y-1">
              {NAV.map(item => (
                <div key={item.p}>
                  <button onClick={() => go(item.p)} className={`block w-full text-left px-3 py-2.5 text-[13px] font-normal uppercase tracking-[0.08em] transition-colors ${cp === item.p ? 'text-[#00aa73] bg-[#f0faf6]' : 'text-[#1c1c1c] hover:text-[#00aa73] hover:bg-gray-50'}`}>{item.l}</button>
                  {item.dd && (
                    <div className="ml-4 space-y-1">
                      {item.dd.map(sub => (<button key={sub} onClick={() => go(item.p)} className="block w-full text-left px-3 py-2 text-[12px] text-[#666] hover:text-[#00aa73] hover:bg-gray-50">{sub}</button>))}
                    </div>
                  )}
                </div>
              ))}
            </div>
            <div className="pt-3 border-t border-gray-200">
              <a href="https://www.festo.com" target="_blank" rel="noopener noreferrer" className="block w-full text-left px-3 py-2.5 text-[12px] text-[#00aa73]">Festo.com &rarr;</a>
            </div>
          </div>
        </div>
      )}
    </header>
  )
}

